"""把模型本轮完整阅读后撰写的研究内容组织成可入库JSON；不自动摘要原文。"""
import copy,json,pathlib,sys
sys.stdout.reconfigure(encoding='utf-8')
B=pathlib.Path(__file__).parent
S=json.loads((B/'source.json').read_text(encoding='utf-8-sig'))
SID,REV=S['source_id'],S['revision']
PREFIX=SID+'/standard-20261023/'
READ=[f'ch-{n+1:04d}' for n in range(1,50)]
def E(n,a=None,b=None,k='fact'):
 c=S['chapters'][n]
 return {'source_id':SID,'revision':REV,'chapter_id':c['chapter_id'],'start_line':a or c['start_line'],'end_line':b or c['end_line'],'claim_kind':k}
def es(*args,k='fact'):
 return [E(*a,k=k) if isinstance(a,tuple) else E(a,k=k) for a in args]
def O(text,evidence,k='inference',**more):
 return {'claim':text,'claim_kind':k,'evidence':evidence,**more}
cards=[]
def card(kind,slug,title,summary,evidence,tags,**content):
 d={'asset_type':kind,'scope':'reusable-pattern' if kind=='pattern' else 'source-analysis','title':title,'origin_key':PREFIX+slug,'tags':['作者:失落叶','作品:网游之纵横天下']+tags,'content':{'summary':summary,**content},'evidence':evidence,'user_notes':'','favorite':False,'review_status':'draft'}
 cards.append(d);return d
def char(slug,title,aliases,summary,facts,interpretation,evidence,old=None):
 return card('character','character-'+slug,title+'｜卷一阶段观察',summary,evidence,['人物','阶段:卷一'],aliases=aliases,phase_scope={'chapter_ids':READ,'description':'仅卷一第1—49章，后续成长未知'},identity_note='这是同一来源人物的阶段观察，不是新增同名独立人物；不能据此覆盖旧卡人工笔记。',same_character_as=old or [],textual_observations=facts,research_interpretation=interpretation,review_boundary='研究判断尚未经用户审美认可。')
